definition.script:
var expr = input.get('expression') || '';
var varsJson = input.get('variables') || '{}';
var precision = parseInt(input.get('precision') || '-1');

if (!expr) {
    output.set('HasErrors', true);
    output.set('ErrorMessage', 'Expression is required');
    tags.trigger('error');
} else {
    try {
        var vars = json.parse(varsJson);

        var tokens = [];
        var i = 0;
        var s = expr.replace(/\s+/g, '');

        while (i < s.length) {
            var c = s.charAt(i);
            if ('0123456789.'.indexOf(c) >= 0) {
                var num = '';
                while (i < s.length && '0123456789.'.indexOf(s.charAt(i)) >= 0) {
                    num += s.charAt(i); i++;
                }
                tokens.push({type: 'num', val: parseFloat(num)});
            } else if ('abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ_'.indexOf(c) >= 0) {
                var name = '';
                while (i < s.length && 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ_0123456789'.indexOf(s.charAt(i)) >= 0) {
                    name += s.charAt(i); i++;
                }
                tokens.push({type: 'id', val: name});
            } else if ('+-*/^%()'.indexOf(c) >= 0) {
                tokens.push({type: 'op', val: c}); i++;
            } else if (c === ',') {
                tokens.push({type: 'comma'}); i++;
            } else {
                i++;
            }
        }

        var pos = 0;
        function peek() { return pos < tokens.length ? tokens[pos] : null; }
        function consume() { return tokens[pos++]; }

        function parseExpr() {
            var left = parseTerm();
            while (peek() && peek().type === 'op' && (peek().val === '+' || peek().val === '-')) {
                var op = consume().val;
                var right = parseTerm();
                left = op === '+' ? left + right : left - right;
            }
            return left;
        }

        function parseTerm() {
            var left = parsePower();
            while (peek() && peek().type === 'op' && (peek().val === '*' || peek().val === '/' || peek().val === '%')) {
                var op = consume().val;
                var right = parsePower();
                if (op === '*') left = left * right;
                else if (op === '/') left = left / right;
                else left = left % right;
            }
            return left;
        }

        function parsePower() {
            var left = parseUnary();
            if (peek() && peek().type === 'op' && peek().val === '^') {
                consume();
                var right = parsePower();
                left = Math.pow(left, right);
            }
            return left;
        }

        function parseUnary() {
            if (peek() && peek().type === 'op' && peek().val === '-') {
                consume();
                return -parsePrimary();
            }
            if (peek() && peek().type === 'op' && peek().val === '+') {
                consume();
            }
            return parsePrimary();
        }

        function parsePrimary() {
            var t = peek();
            if (!t) throw new Error('Unexpected end');
            if (t.type === 'num') { consume(); return t.val; }
            if (t.type === 'op' && t.val === '(') {
                consume();
                var v = parseExpr();
                if (peek() && peek().type === 'op' && peek().val === ')') consume();
                return v;
            }
            if (t.type === 'id') {
                var name = consume().val;
                if (peek() && peek().type === 'op' && peek().val === '(') {
                    consume();
                    var args = [];
                    while (peek() && !(peek().type === 'op' && peek().val === ')')) {
                        args.push(parseExpr());
                        if (peek() && peek().type === 'comma') consume();
                    }
                    if (peek()) consume();
                    var fn = name.toLowerCase();
                    if (fn === 'sqrt') return Math.sqrt(args[0]);
                    if (fn === 'abs') return Math.abs(args[0]);
                    if (fn === 'floor') return Math.floor(args[0]);
                    if (fn === 'ceil') return Math.ceil(args[0]);
                    if (fn === 'round') return Math.round(args[0]);
                    if (fn === 'sin') return Math.sin(args[0]);
                    if (fn === 'cos') return Math.cos(args[0]);
                    if (fn === 'tan') return Math.tan(args[0]);
                    if (fn === 'log') return Math.log(args[0]);
                    if (fn === 'log10') return Math.log10(args[0]);
                    if (fn === 'exp') return Math.exp(args[0]);
                    if (fn === 'pow') return Math.pow(args[0], args[1]);
                    if (fn === 'min') return Math.min.apply(null, args);
                    if (fn === 'max') return Math.max.apply(null, args);
                    throw new Error('Unknown function: ' + name);
                }
                if (name.toLowerCase() === 'pi') return Math.PI;
                if (name.toLowerCase() === 'e') return Math.E;
                if (vars[name] !== undefined) return parseFloat(vars[name]);
                throw new Error('Unknown variable: ' + name);
            }
            throw new Error('Unexpected token');
        }

        var result = parseExpr();

        if (precision >= 0) {
            result = parseFloat(result.toFixed(precision));
        }

        output.set('Result', result);
        output.set('ResultString', result.toString());
        output.set('IsInteger', result % 1 === 0);
        output.set('IsPositive', result > 0);
        output.set('IsNegative', result < 0);
        output.set('IsZero', result === 0);
        output.set('AbsoluteValue', Math.abs(result));
        output.set('Expression', expr);
        output.set('HasErrors', false);
        output.set('ErrorMessage', '');

        log.info('Evaluated: ' + expr + ' = ' + result);
        tags.trigger('success');

    } catch (ex) {
        log.error('Evaluation failed: ' + ex.message);
        output.set('HasErrors', true);
        output.set('ErrorMessage', ex.message);
        tags.trigger('error');
    }
}
